CREATE TABLE users (name TEXT, age INT);
INSERT INTO users VALUES
  ('An', 25), ('Binh', 30), ('Chi', NULL), ('Dung', 40);

SELECT COUNT(*) FROM users WHERE age <> 30;

CREATE TABLE customers (name TEXT, city TEXT);
INSERT INTO customers VALUES
  ('An', 'Ha Noi'), ('Binh', 'HCM'), ('Chi', 'Ha Noi'),
  ('Dung', NULL), ('Giang', NULL);

SELECT DISTINCT city FROM customers;

CREATE TABLE users (id INT, name TEXT);
INSERT INTO users VALUES
  (1, 'Lan'), (2, 'Anh'), (3, 'Tuan'), (4, 'Hanh');

SELECT name FROM users
WHERE name LIKE '_an%'
ORDER BY id;

CREATE TABLE products (name TEXT, price INT);
INSERT INTO products VALUES
  ('A', 10), ('B', 50), ('C', 30), ('D', 20), ('E', 40);

SELECT name FROM products
ORDER BY price DESC
LIMIT 2 OFFSET 1;

CREATE TABLE employees (name TEXT, salary INT, bonus INT);
INSERT INTO employees VALUES
  ('An', 1000, 200), ('Binh', 1200, NULL);

-- Expected: total income of each employee
SELECT name, salary + bonus AS total
FROM employees;

CREATE TABLE customers (id INT, name TEXT);
CREATE TABLE orders (id INT, customer_id INT);
INSERT INTO customers VALUES (1, 'An'), (2, 'Binh'), (3, 'Chi');
INSERT INTO orders VALUES (10, 1), (11, 1), (12, 2);

SELECT COUNT(*)
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id;

CREATE TABLE sizes (size TEXT);
CREATE TABLE colors (color TEXT);
INSERT INTO sizes VALUES ('S'), ('M'), ('L');
INSERT INTO colors VALUES ('Red'), ('Blue'), ('Black'), ('White');

SELECT COUNT(*) FROM sizes CROSS JOIN colors;

CREATE TABLE orders (id INT, amount INT);
CREATE TABLE payments (order_id INT, paid INT);
INSERT INTO orders VALUES (1, 100), (2, 50);
INSERT INTO payments VALUES (1, 60), (1, 40), (2, 50);

SELECT SUM(o.amount) AS total_amount
FROM orders o
JOIN payments p ON p.order_id = o.id;

CREATE TABLE customers (id INT, name TEXT);
CREATE TABLE orders (id INT, customer_id INT);
INSERT INTO customers VALUES (1, 'An'), (2, 'Binh'), (3, 'Chi');
INSERT INTO orders VALUES (10, 1), (11, 3);

SELECT c.name
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.id IS NULL;

CREATE TABLE orders (id INT, customer TEXT, amount INT);
INSERT INTO orders VALUES
  (1, 'An', 100), (2, 'An', 300), (3, 'Binh', 500),
  (4, 'Chi', 200), (5, 'Chi', 150), (6, 'Chi', 50);

SELECT customer, SUM(amount) AS total
FROM orders
GROUP BY customer
HAVING COUNT(*) >= 2 AND SUM(amount) > 350
ORDER BY customer;

CREATE TABLE t (x INT);
INSERT INTO t VALUES (1), (NULL), (2), (2), (NULL);

SELECT COUNT(*), COUNT(x), COUNT(DISTINCT x) FROM t;

CREATE TABLE reviews (product TEXT, rating INT);
INSERT INTO reviews VALUES ('A', 4), ('A', 2), ('A', NULL);

SELECT AVG(rating) FROM reviews;

SELECT customer_id, status, COUNT(*) AS total
FROM orders
GROUP BY customer_id;

CREATE TABLE scores (name TEXT, score INT);
INSERT INTO scores VALUES ('An', 90), ('Binh', 90), ('Chi', 80);

SELECT name,
       RANK() OVER (ORDER BY score DESC) AS rnk,
       DENSE_RANK() OVER (ORDER BY score DESC) AS dense
FROM scores;

CREATE TABLE sales (day INT, amount INT);
INSERT INTO sales VALUES (1, 10), (2, 20), (3, 30);

SELECT day,
       SUM(amount) OVER (ORDER BY day) AS running
FROM sales
ORDER BY day;

CREATE TABLE orders (id INT, status TEXT);
INSERT INTO orders VALUES
  (1, 'paid'), (2, 'paid'), (3, 'cancelled'), (4, 'paid');

-- Expected: 75 (percent of paid orders)
SELECT SUM(CASE WHEN status = 'paid' THEN 1 ELSE 0 END)
       / COUNT(*) * 100 AS paid_pct
FROM orders;

CREATE TABLE a (x INT);
CREATE TABLE b (x INT);
INSERT INTO a VALUES (1), (2), (2);
INSERT INTO b VALUES (2), (3);

SELECT x FROM a
UNION
SELECT x FROM b;

CREATE TABLE customers (id INT, name TEXT);
CREATE TABLE orders (id INT, customer_id INT);
INSERT INTO customers VALUES (1, 'An'), (2, 'Binh'), (3, 'Chi');
INSERT INTO orders VALUES (10, 1), (11, NULL);

SELECT COUNT(*) FROM customers
WHERE id NOT IN (SELECT customer_id FROM orders);

CREATE TABLE employees (name TEXT, salary INT);
INSERT INTO employees VALUES
  ('An', 10), ('Binh', 20), ('Chi', 30), ('Dung', 40);

SELECT name FROM employees
WHERE salary > (SELECT AVG(salary) FROM employees)
ORDER BY name;

WITH RECURSIVE n(x) AS (
  SELECT 1
  UNION ALL
  SELECT x + 1 FROM n WHERE x < 5
)
SELECT SUM(x) FROM n;

SELECT id, name
FROM employees
WHERE dept_id = (
  SELECT id FROM departments
  WHERE name LIKE 'Sales%'
);

CREATE TABLE customers (id INT PRIMARY KEY);
CREATE TABLE orders (
  id INT PRIMARY KEY,
  customer_id INT REFERENCES customers(id) ON DELETE CASCADE
);
INSERT INTO customers VALUES (1), (2);
INSERT INTO orders VALUES (10, 1), (11, 1), (12, 2);

DELETE FROM customers WHERE id = 1;
SELECT COUNT(*) FROM orders;

CREATE TABLE wallets (id INT, balance REAL);
INSERT INTO wallets VALUES (1, 0.1);
UPDATE wallets SET balance = balance + 0.2 WHERE id = 1;

SELECT id FROM wallets WHERE balance = 0.3;

-- CREATE INDEX idx_orders_created ON orders(created_at);
SELECT id, total
FROM orders
WHERE DATE(created_at) = '2024-05-01';

-- CREATE INDEX idx_users_email ON users(email);
SELECT id FROM users
WHERE email LIKE '%@gmail.com';

CREATE TABLE accounts (id INT, balance INT);
INSERT INTO accounts VALUES (1, 500);

BEGIN;
UPDATE accounts SET balance = balance - 200 WHERE id = 1;
ROLLBACK;

SELECT balance FROM accounts WHERE id = 1;

CREATE TABLE logs (id INT);

BEGIN;
INSERT INTO logs VALUES (1);
SAVEPOINT sp1;
INSERT INTO logs VALUES (2);
ROLLBACK TO SAVEPOINT sp1;
INSERT INTO logs VALUES (3);
COMMIT;

SELECT id FROM logs ORDER BY id;
